#include <bits/stdc++.h>
using namespace std;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);
 int n,k;long long L;cin>>n>>L>>k;vector<long long> cut(n);for(auto&x:cut)cin>>x;cut.push_back(L);
 auto feasible=[&](long long x){int pieces=0;long long last=0;for(long long at:cut)if(at-last>=x){++pieces;last=at;}return pieces>=k+1;};
 long long lo=0,hi=L+1;while(hi-lo>1){long long mid=lo+(hi-lo)/2;if(feasible(mid))lo=mid;else hi=mid;}cout<<lo<<char(10);
}

