 while(q--){long long b;cin>>b;auto it=lower_bound(a.begin(),a.end(),b);long long ans=LLONG_MAX;if(it!=a.end())ans=min(ans,llabs(*it-b));if(it!=a.begin())ans=min(ans,llabs(*prev(it)-b));cout<<ans<<char(10);}
